-- Counter & Shop Helper (Paladins 8.1, id paladins-smartcounter-81): in-game panel and menu.
--
-- This file only wires the modules together and runs the frame:
--
--   lib/sc_data.lua      strategy data + game ids (generated by engine/export_lua.py, no game text)
--   lib/sc_predictor.lua build / threat / counter prediction (Lua port of engine/predictor.py)
--   lib/sc_detect.lua    the match as the game sees it (reflection, read-only, 1 Hz)
--   lib/sc_player.lua    the local player's owned items and ranks (reflection, read-only)
--   lib/sc_text.lua      names and descriptions from the game, in the game's language
--   lib/sc_lang.lua      the mod's own UI strings (8 languages)
--   lib/sc_config.lua    settings (tempest.config / tempest.save_config)
--   lib/sc_keys.lua      hotkeys (tempest.on_key) and rebinding
--   lib/sc_match.lua     inputs -> prediction, rerun only when an input changes
--   lib/sc_fonts.lua     Windows fonts through ui.add_font
--   lib/sc_gui.lua       guarded ImGui, palette, theme
--   lib/sc_view.lua      the panel (compact / detailed)
--   lib/sc_menu.lua      the menu and the tutorial
--
-- Nothing is sent to the game: the mod reads, computes and draws. Cost per frame while shown: one
-- signature string, a few widgets; detection and item reading are throttled in their modules.
-- Made by Machi Konno  ·  Discord: machi.konno

local VERSION = "0.6.4"
local AUTHOR, DISCORD = "Machi Konno", "machi.konno"

local function log(fmt, ...)
	tempest.log("[smartcounter] " .. string.format(fmt, ...))
end

local DATA = require("lib.sc_data")
local Predictor = require("lib.sc_predictor")
local Detect = require("lib.sc_detect")
local Player = require("lib.sc_player")
local Text = require("lib.sc_text")
local L = require("lib.sc_lang")
local Config = require("lib.sc_config")
local Keys = require("lib.sc_keys")
local Match = require("lib.sc_match")
local Fonts = require("lib.sc_fonts")
local G = require("lib.sc_gui")
local View = require("lib.sc_view")
local Menu = require("lib.sc_menu")

-- Survives a hot reload: mouse capture to release, tip already shown, loaded font sets, last layout.
shared.smartcounter = shared.smartcounter or {}
local S = shared.smartcounter
S.font_sets = S.font_sets or {}
if S.captured then
	pcall(ui.capture, false)
	S.captured = false
end

local PRED = Predictor.new(DATA)
local DET = Detect.new(PRED)
local PLAYER = Player.new(DATA, log)
local TX = Text.new(DATA, PRED)
local CFG = Config.load(L.valid, function(name)
	local c = PRED:champion(name)
	return c and c.name
end, log)
local cfg = CFG.values
local MATCH = Match.new(cfg, DATA, PRED, DET, PLAYER, log)
local FONTS = Fonts.new(L, TX, S.font_sets, log)

-- ------------------------------------------------------------------ app context
-- Everything the view and the menu need, in one table.
local A = {
	VERSION = VERSION, AUTHOR = AUTHOR, DISCORD = DISCORD,
	D = DATA, PRED = PRED, DET = DET, PLAYER = PLAYER, TX = TX, L = L, t = L.t,
	cfg = cfg, CFG = CFG, MATCH = MATCH, G = G, S = S,
	state = { menu_open = false, overlay_on = cfg.show_on_start },
}

-- The game's language as a UI language ("en" until the game tells).
function A.game_lang()
	return TX:ui_lang() or "en"
end

function A.ui_lang()
	return cfg.lang == "auto" and A.game_lang() or cfg.lang
end

local font_set = FONTS:set_for(A.ui_lang())

function A.with_font(kind, fn)
	return FONTS:with(font_set, kind, cfg.text_size, fn)
end

-- Measured widths depend on the font actually in use.
function A.font_key()
	return font_set.key .. ":" .. font_set.state
end

function A.bold(c, s)
	A.with_font("bold", function() G.tcol(c, s) end)
end

function A.set_lang(lang)
	if (lang == "auto" or L.valid(lang)) and cfg.lang ~= lang then
		cfg.lang = lang
		L.set(A.ui_lang())
		CFG:mark_dirty()
	end
end

-- Match tab button: what the item reader sees now, written to the Tempest log (one block per press).
function A.items_diag()
	PLAYER:refresh()
	for _, line in ipairs(PLAYER:describe(DET.state.status)) do log("%s", line) end
	A.toast(A.t("owned_diag_done"))
end

local VIEW = View.new(A)
local MENU = Menu.new(A, VIEW)

function A.set_menu(on)
	A.state.menu_open = on
	if on then PLAYER:refresh() end   -- read the items now, not at the next poll
	if on and not cfg.tutorial_done and not MENU.tut_step then MENU.tut_step = 1 end
	local ok = pcall(ui.capture, on)   -- the mouse goes to the menu only while it is open
	S.captured = on and ok
	if not on then A.KEYS:stop() end
end

-- ------------------------------------------------------------------ hotkeys
-- Key and console callbacks only queue the action; the next frame runs it, on the draw thread, where
-- ImGui, ui.capture and toasts are valid.
local pending = {}

local function toast(s)
	pcall(tempest.toast, s)
end
A.toast = toast

local function run_action(id)
	local t = L.t
	if id == "menu" then
		A.set_menu(not A.state.menu_open)
	elseif id == "overlay" then
		A.state.overlay_on = not A.state.overlay_on
	elseif id == "settings" then
		if A.state.menu_open and MENU.cur_tab == "settings" then
			A.set_menu(false)
		else
			A.set_menu(true)
			MENU:open_tab("settings")
		end
	elseif id == "lock" then
		cfg.locked = not cfg.locked
		CFG:mark_dirty()
		toast(t(cfg.locked and "locked" or "unlocked"))
	elseif id == "layout" then
		-- compact <-> detailed (from Auto: the opposite of what is shown right now)
		local shown = cfg.display == "auto" and (S.last_mode or "compact") or cfg.display
		cfg.display = shown == "compact" and "detailed" or "compact"
		A.state.overlay_on = true
		CFG:mark_dirty()
		toast(t("layout_now", t("disp_" .. cfg.display)))
	end
end

local function on_action(id)
	pending[#pending + 1] = id
	return true   -- the key is consumed (not passed to the game)
end

local function run_pending()
	if #pending == 0 then return end
	local list = pending
	pending = {}
	for _, id in ipairs(list) do run_action(id) end
end

A.KEYS = Keys.new(CFG, Config.DEFAULT_KEYS, L.t, log, on_action)
A.KEYS:bind_all()
L.set(A.ui_lang())

-- ------------------------------------------------------------------ frame
local last_game

-- What belongs to one game is dropped when a new one starts (DET names games by their roster).
local function follow_game(st)
	if st.game and st.game ~= last_game then
		last_game = st.game
		MATCH.cs_me = nil   -- my pick in an earlier champion select
		if next(cfg.owned) then cfg.owned = {} end   -- manual item ranks of the last game
	end
	if (st.status == "champ_select" or st.status == "loading") and st.me then MATCH.cs_me = st.me end
end

-- Detection and item reading, only while something is shown.
local function read_game(now)
	local st = DET.state
	if cfg.auto_detect then
		st = DET:poll(now)
		follow_game(st)
	end
	-- no item reading while a world is loading or being torn down, or without a player; a practice
	-- map (training, range: "loading" with nothing loading) is read
	local busy = st.status == "match_over" or st.status == "no_player" or (st.status == "loading" and not st.practice)
	if st.status ~= S.logged_status or (st.practice or false) ~= S.logged_practice then
		S.logged_status, S.logged_practice = st.status, st.practice or false
		log("status: %s%s (map %s)%s", st.status, st.practice and ", practice map" or "", tostring(st.map),
			(cfg.live_items and busy) and ", item reading paused" or "")
	end
	if cfg.live_items and not busy then PLAYER:poll(now) end
end

local function frame()
	local now = os.clock()
	run_pending()
	TX:refresh(now)
	if L.lang ~= A.ui_lang() then L.set(A.ui_lang()) end   -- Auto follows the game's language
	TX:set_view(A.ui_lang(), cfg.game_names)   -- game names only in the language shown (see sc_text)
	font_set = FONTS:tick(now, A.ui_lang())
	if cfg.show_tip and not S.tip_done then VIEW:draw_tip(now) end
	local shown = A.state.overlay_on or A.state.menu_open
	if shown then
		read_game(now)
		MATCH:update()
		G.with_theme(function()
			if A.state.overlay_on then VIEW:draw_overlay(now) end
			if A.state.menu_open then MENU:draw() end
		end)
	end
	CFG:tick(now)
end

local draw_failed = false
ui.on_draw(function()
	local ok, err = pcall(frame)
	if not ok and not draw_failed then
		draw_failed = true
		log("draw error (logged once): %s", tostring(err))
	end
end)

tempest.command("smartcounter", function()
	on_action("menu")
end, "Counter & Shop Helper: open / close the menu")

log("loaded v%s (%s, %d champions, UI language %s, keys %s/%s/%s/%s/%s, live items %s)",
	VERSION, DATA.build, #DATA.champions, cfg.lang, cfg.keys.menu, cfg.keys.overlay, cfg.keys.settings,
	cfg.keys.lock, cfg.keys.layout, cfg.live_items and "on" or "off")
